(function(){
  function parseSize(s){
    s=String(s||'').trim();
    var m=s.match(/^([\d.]+)\s*([KMGT]?)B?$/i);
    if(!m) return parseFloat(s)||0;
    var n=parseFloat(m[1]), u=m[2].toUpperCase();
    var mul={'':1,'K':1024,'M':1024*1024,'G':1024*1024*1024,'T':1024*1024*1024*1024}[u]||1;
    return n*mul;
  }
  function table(text){
    var lines=String(text||'').split(/\r?\n/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var rows=[];
    lines.forEach(function(l){
      var p=l.split(/\s+/); if(p.length<4) return;
      var total=parseSize(p[1]), used=parseSize(p[2]), avail=parseSize(p[3]);
      var pct= total? Math.round(used/total*100):0;
      var n=Math.min(40,Math.max(1,Math.round(pct*40/100)));
      rows.push({name:p[0], total:total, used:used, avail:avail, pct:pct, bar:'█'.repeat(n)+'░'.repeat(40-n)});
    });
    rows.sort(function(a,b){return b.pct-a.pct;});
    return {value: rows};
  }
  var API={table:table, parseSize:parseSize};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__DufForge__=API;
})();
